const upsertMerchantPayoutAccount = `-- name: UpsertMerchantPayoutAccount :one
INSERT INTO merchant_payout_accounts (
    workspace_id, provider, bank_code, account_number_last4, account_name, subaccount_ref, status, updated_at
) VALUES ($1, $2, $3, $4, $5, $6, $7, now())
ON CONFLICT (workspace_id, provider) DO UPDATE
SET bank_code = EXCLUDED.bank_code,
    account_number_last4 = EXCLUDED.account_number_last4,
    account_name = EXCLUDED.account_name,
    subaccount_ref = EXCLUDED.subaccount_ref,
    status = EXCLUDED.status,
    updated_at = now()
RETURNING id, workspace_id, provider, bank_code, account_number_last4, account_name, subaccount_ref, status, created_at, updated_at
`

type UpsertMerchantPayoutAccountParams struct {
	WorkspaceID        int64  `json:"workspace_id"`
	Provider           string `json:"provider"`
	BankCode           string `json:"bank_code"`
	AccountNumberLast4 string `json:"account_number_last4"`
	AccountName        string `json:"account_name"`
	SubaccountRef      string `json:"subaccount_ref"`
	Status             string `json:"status"`
}

func (q *Queries) UpsertMerchantPayoutAccount(ctx context.Context, arg UpsertMerchantPayoutAccountParams) (MerchantPayoutAccount, error) {
	row := q.db.QueryRow(ctx, upsertMerchantPayoutAccount,
		arg.WorkspaceID,
		arg.Provider,
		arg.BankCode,
		arg.AccountNumberLast4,
		arg.AccountName,
		arg.SubaccountRef,
		arg.Status,
	)
	var i MerchantPayoutAccount
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Provider,
		&i.BankCode,
		&i.AccountNumberLast4,
		&i.AccountName,
		&i.SubaccountRef,
		&i.Status,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertShopper = `-- name: UpsertShopper :one
INSERT INTO shoppers (email, name, phone, last_seen_at)
VALUES (lower(btrim($1)), $2, $3, now())
ON CONFLICT (email) DO UPDATE
SET last_seen_at = now(),
    name = COALESCE(EXCLUDED.name, shoppers.name),
    phone = COALESCE(EXCLUDED.phone, shoppers.phone)
RETURNING id, email, name, phone, saved_addresses, created_at, last_seen_at
`

type UpsertShopperParams struct {
	Btrim string      `json:"btrim"`
	Name  pgtype.Text `json:"name"`
	Phone pgtype.Text `json:"phone"`
}

func (q *Queries) UpsertShopper(ctx context.Context, arg UpsertShopperParams) (Shopper, error) {
	row := q.db.QueryRow(ctx, upsertShopper, arg.Btrim, arg.Name, arg.Phone)
	var i Shopper
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.Name,
		&i.Phone,
		&i.SavedAddresses,
		&i.CreatedAt,
		&i.LastSeenAt,
	)
	return i, err
}
